[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(Mandatory=$true)][string]$PacketPath)
$ErrorActionPreference='Stop';$root=(Resolve-Path $ProjectRoot).Path;if([IO.Path]::IsPathRooted($PacketPath)){throw 'PacketPath must be project-relative.'};$rel=$PacketPath.Replace('\','/').Trim();if($rel.Contains('..')-or $rel -notmatch '^ES/Output/.+\.json$'){throw 'PacketPath must remain under ES/Output.'};$full=Join-Path $root ($rel.Replace('/',[IO.Path]::DirectorySeparatorChar));if(-not(Test-Path $full -PathType Leaf)){throw "Prefab validation packet missing: $rel"};$p=[Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes((Resolve-Path $full)))|ConvertFrom-Json;foreach($x in @('EntityId','PrefabGuid','DataInfo','Parts','Owner','InitOrder','InputControl','Motion','Pool','ResourceScope','Cleanup','EvidenceRef','StaleWhen')){if($null -eq $p.PSObject.Properties[$x]){throw "Prefab field missing: $x"}};if([string]$p.PrefabGuid -notmatch '^[0-9a-fA-F]{32}$'-or @($p.Parts).Count -eq 0){throw 'Prefab identity or Parts are invalid.'};if([string]$p.Pool -eq 'unowned'-or [string]$p.ResourceScope -eq 'global'){throw 'Prefab cannot use unowned Pool or global ResourceScope.'};if([string]$p.EvidenceRef -eq 'not-run'-and [string]$p.Cleanup -eq 'accepted'){throw 'Accepted prefab validation requires runtime evidence.'};Write-Output "PASS: Entity Prefab matrix covers stable identity, DataInfo, Parts, ownership, Pool, Scope and cleanup: $rel"
